WITH attributed AS (SELECT src.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM promotions src INNER JOIN promotions pr ON COALESCE(src.channel, 'store') = pr.channel AND src.ends_on >= pr.starts_on AND src.ends_on < pr.ends_on + INTERVAL '14' DAY) SELECT DATE_TRUNC('YEAR', ends_on) AS year_start, DATE_TRUNC('QUARTER', ends_on) AS quarter_start, DATE_TRUNC('MONTH', starts_on) AS activity_month, APPROX_PERCENTILE(discount_pct, 0.5) AS discount_pct_p50, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN promo_code = 'SPRING10' THEN 1 END), 0), 2) AS discount_pct_per_spring10, ROUND(SUM(promotion_discount_pct) / NULLIF(COUNT(CASE WHEN promo_code = 'BUNDLE' THEN 1 END), 0), 2) AS promotion_discount_pct_per_bundle, COUNT_IF(channel = 'store') AS store_events FROM attributed GROUP BY CUBE (DATE_TRUNC('YEAR', ends_on), DATE_TRUNC('QUARTER', ends_on), DATE_TRUNC('MONTH', starts_on)) ORDER BY store_events;
